head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil20400";
scwin.layoutDisclsAnalysisChart = '/chart5/LayoutXml/quotation_Layout.txt';
scwin.dataDisclsAnalysisChart = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — quotationList

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_125", fn: function(){ return (!(String(((dma_pageContext.get("quotationList") ?? "")) == null ? '' : ((dma_pageContext.get("quotationList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_sdate", fn: function () { return String(String((dma_pageContext.get("sdate") ?? ""))); } },
        { childId: "cal_edate", fn: function () { return String(String((dma_pageContext.get("edate") ?? ""))); } },
        { childId: "__rb0", fn: function () { return "기준일 : " + String(dma_currentQuotation.get("trdDd")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dataDisclsAnalysisChart =[

        {"open":(String(((dlt_quotationList.getCellData(0, "tddOpnprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddOpnprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddOpnprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddOpnprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddOpnprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddOpnprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddOpnprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddOpnprc"); })())))),"admnt":(String(((dlt_quotationList.getCellData(0, "accTrdvol") ?? (() => { throw new Error("unresolved:" + "quotationInfo.accTrdvol"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "accTrdvol") ?? (() => { throw new Error("unresolved:" + "quotationInfo.accTrdvol"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "accTrdvol") ?? (() => { throw new Error("unresolved:" + "quotationInfo.accTrdvol"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "accTrdvol") ?? (() => { throw new Error("unresolved:" + "quotationInfo.accTrdvol"); })())))),"high":(String(((dlt_quotationList.getCellData(0, "tddHgprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddHgprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddHgprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddHgprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddHgprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddHgprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddHgprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddHgprc"); })())))),"low":(String(((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })())))),"date":(String(((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())))),"close":(String(((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })()))))},

    ]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil20400' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil20400.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ClickPeriod_onclick
 * @description 「1주」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ClickPeriod_onclick = async function(e){
    try {
        await scwin.setSearchPeriod(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20400.btn_ClickPeriod_onclick' }); }
};

