/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil20400.btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/companyinfo.do",
        ref: "dma_SearchReq",
        target: "dlt_quotationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_quotationList_fmt_fluc
 * @description grd quotation List fmt fluc 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_quotationList_fmt_fluc = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_quotationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "flucTpCd") ?? '') : '');
        if (v === '1') { return "▲"; }
        if (v === '2') { return "▼"; }
        if (v === '4') { return "↑"; }
        if (v === '5') { return "↓"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_quotationList.fluc" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.quotationForm || { elements: [] });
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'searchQuotation');
    frm.action = 'companyinfo.do';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name fnChartReadyHandlerDisclsAnalysisChart
 * @description fn Chart Ready Handler Discls Analysis Chart 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.fnChartReadyHandlerDisclsAnalysisChart = function (id) {
    $c.util.getComponent(id).setLayoutURL(scwin.layoutDisclsAnalysisChart);
    $c.util.getComponent(id).setData(scwin.dataDisclsAnalysisChart);
};

/**
 * @method
 * @name fnDataTipFunc
 * @description fn Data Tip Func 처리
 * @param {String} seriesId seriesId
 * @param {*} seriesName seriesName
 * @param {Number} index index
 * @param {*} xName xName
 * @param {*} yName yName
 * @param {*} data 데이터
 * @param {*} values values
 * @returns {void}
 * @hidden N
 */
scwin.fnDataTipFunc = function (seriesId, seriesName, index, xName, yName, data, values) {
    if (data.gongsi) {
        scwin.fnSetGongsiData(data);
    } else {
        scwin.fnSetNoActiveFromDisclsView();
    }
    return "[" + data.date + "]<br>시 : " + data.open.format() + "<br>고 : " + data.high.format() + "<br>저 : " + data.low.format() + "<br>종 : " + data.close.format() + "<br>거 : " + data.admnt.format();
};

/**
 * @method
 * @name fnSetGongsiData
 * @description fn Set Gongsi Data 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSetGongsiData = function (data) {
    if (typeof data === "object") {
        scwin.fnSetNoActiveFromDisclsView();
        const varObj = $(document).find("tbody[id=disclsView]");
        varObj.find("tr[id=disclsDate-" + data.date + "]").each(function() {
                if ($(this).hasClass("first")) {
                    $(this).removeClass("first");
                    $(this).addClass("active");
                }
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        });
    }
};

/**
 * @method
 * @name fnSetNoActiveFromDisclsView
 * @description fn Set No Active From Discls View 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSetNoActiveFromDisclsView = function () {
    const varObj = $(document).find("tbody[id=disclsView]");
    varObj/* 수동 전환 필요: 행 순회(find(tr)) — 컨테이너·목록을 못 정함 · to-be 에 돌 요소가 없다 */ .find("tr").each(function() {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
                $(this).addClass("first");
            }
    });
};

/**
 * @method
 * @name fnMaxLabelFunc
 * @description fn Max Label Func 처리
 * @param {String} seriesId seriesId
 * @param {Number} index index
 * @param {*} data 데이터
 * @param {*} values values
 * @returns {void}
 * @hidden N
 */
scwin.fnMaxLabelFunc = function (seriesId, index, data, values) {
    const max = scwin.fnGetTypeNum(values.slice(1, values.length));
    return "<font color='#ff0000'>최고 : <b>" + max[2].format() + "</b> (" + values[0] + ")</font>";
};

/**
 * @method
 * @name fnMinLabelFunc
 * @description fn Min Label Func 처리
 * @param {String} seriesId seriesId
 * @param {Number} index index
 * @param {*} data 데이터
 * @param {*} values values
 * @returns {void}
 * @hidden N
 */
scwin.fnMinLabelFunc = function (seriesId, index, data, values) {
    const min = scwin.fnGetTypeNum(values.slice(1, values.length));
    return "<font color='#0000ff'>최저 : <b>" + min[min.length - 1].format() + "</b> (" + values[0] + ")</font>";
};

/**
 * @method
 * @name fnGetTypeNum
 * @description fn Get Type Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnGetTypeNum = function () {
    return Array.prototype.slice.call(arguments, 0).sort()[0];
};

/**
 * @method
 * @name setSearchPeriod
 * @description 조회 기간 버튼 — 오늘을 종료일로, 구분에 따라 시작일을 계산해 넣고 조회(as-is 공통 fn_ClickPeriod)
 * @param {*} type 1 1주 · 2 1개월 · 3 3개월 · 4 6개월 · 5 1년 · 6 2년 · 7 3년
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSearchPeriod = async function (type) {
    const edate = $c.date.getServerDateTime("yyyyMMdd");
    const offsets = { 1: ["addDate", -7], 2: ["addMonth", -1], 3: ["addMonth", -3], 4: ["addMonth", -6], 5: ["addYear", -1], 6: ["addYear", -2], 7: ["addYear", -3] };
    const o = offsets[Number(type)];
    const sdate = o ? $c.date[o[0]](edate, o[1]) : edate;
    await scwin.setPeriodDates(sdate, edate);
};

/**
 * @method
 * @name setPeriodDates
 * @description 조회 기간(시작일·종료일)을 달력에 넣고 바로 조회(as-is 공통 fn_SetPeriod → fn_Search)
 * @param {*} sdate 시작일(yyyyMMdd)
 * @param {*} edate 종료일(yyyyMMdd)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPeriodDates = async function (sdate, edate) {
    $c.util.getComponent("cal_sdate").setValue(sdate);
    $c.util.getComponent("cal_edate").setValue(edate);
    await scwin.search();
};
